Dataspatium.assets.register("presets/api/socialstyrelsen.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"socialstyrelsen\",\n  \"name\": \"Socialstyrelsen Statistikdatabasen\",\n  \"publisher\": \"Socialstyrelsen\",\n  \"description\": \"Dödsorsaker, diagnoser i sluten och öppen vård, läkemedel, operationer, graviditeter och förlossningar, tandhälsa, skador med mera. Välj ämne och värden per variabel; resultatet hämtas i sidor om 5 000 rader.\",\n  \"docs\": \"https://www.socialstyrelsen.se/statistik-och-data/statistik/statistikdatabasen/\",\n  \"license\": { \"name\": \"Se Socialstyrelsens villkor för statistikdatabasen\", \"url\": \"https://www.socialstyrelsen.se/statistik-och-data/statistik/statistikdatabasen/\" },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://sdb.socialstyrelsen.se/api/v1/sv\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 10, \"perSeconds\": 2 },\n  \"family\": { \"type\": \"socialstyrelsen\" },\n  \"endpoints\": [\n    {\n      \"id\": \"subjects\",\n      \"name\": \"Lista ämnen\",\n      \"description\": \"Ämnesområden i statistikdatabasen med deras id.\",\n      \"method\": \"GET\",\n      \"path\": \"\",\n      \"response\": { \"format\": \"json\", \"rename\": { \"namn\": \"id\", \"text\": \"amne\" } },\n      \"dataset\": { \"name\": \"Socialstyrelsen ämnen\" }\n    }\n  ],\n  \"notes\": \"Variabler utan urval hämtas med alla värden. Måttet 'Antal döda per 100 000' med flera är beräknade värden; se databasens beskrivning.\",\n  \"i18n\": {\n    \"en\": {\"name\": \"National Board of Health and Welfare: Statistical Database\", \"publisher\": \"National Board of Health and Welfare (Socialstyrelsen)\", \"description\": \"Swedish statistics on causes of death, diagnoses in inpatient and outpatient care, medicines, operations, pregnancies and births, dental health, injuries and more. Choose a subject and values per variable; the result is fetched in pages of 5,000 rows.\", \"notes\": \"Variables without a selection are fetched with all values. The measure 'Antal döda per 100 000' and others are calculated values; see the database's description.\", \"endpoints\": {\"subjects\": {\"name\": \"List subjects\", \"description\": \"Subject areas in the statistical database with their ids.\"}}, \"dataset\": {\"subjects\": \"Socialstyrelsen subjects\"}},\n    \"da\": {\"name\": \"Socialstyrelsen Statistikdatabasen\", \"publisher\": \"Socialstyrelsen (Sveriges sundheds- og socialstyrelse)\", \"description\": \"Svensk statistik om dødsårsager, diagnoser i stationær og ambulant behandling, lægemidler, operationer, graviditeter og fødsler, tandsundhed, skader med mere. Vælg emne og værdier pr. variabel; resultatet hentes i sider på 5 000 rækker.\", \"notes\": \"Variabler uden udvalg hentes med alle værdier. Målet 'Antal döda per 100 000' med flere er beregnede værdier; se databasens beskrivelse.\", \"endpoints\": {\"subjects\": {\"name\": \"Vis emner\", \"description\": \"Emneområder i statistikdatabasen med deres id.\"}}, \"dataset\": {\"subjects\": \"Socialstyrelsen emner\"}},\n    \"nb\": {\"name\": \"Socialstyrelsen Statistikdatabasen\", \"publisher\": \"Socialstyrelsen (Sveriges helse- og sosialdirektorat)\", \"description\": \"Svensk statistikk om dødsårsaker, diagnoser i døgnbehandling og poliklinisk behandling, legemidler, operasjoner, svangerskap og fødsler, tannhelse, skader med mer. Velg emne og verdier per variabel; resultatet hentes i sider på 5 000 rader.\", \"notes\": \"Variabler uten utvalg hentes med alle verdier. Målet 'Antal döda per 100 000' med flere er beregnede verdier; se databasens beskrivelse.\", \"endpoints\": {\"subjects\": {\"name\": \"List emner\", \"description\": \"Emneområder i statistikkdatabasen med deres id.\"}}, \"dataset\": {\"subjects\": \"Socialstyrelsen emner\"}},\n    \"fi\": {\"name\": \"Socialstyrelsen: tilastotietokanta\", \"publisher\": \"Socialstyrelsen (Ruotsin sosiaali- ja terveysalan viranomainen)\", \"description\": \"Ruotsin tilastot kuolemansyistä, diagnooseista laitos- ja avohoidossa, lääkkeistä, leikkauksista, raskauksista ja synnytyksistä, suunterveydestä, vammoista ja muusta. Valitse aihe ja arvot muuttujittain; tulos noudetaan 5 000 rivin sivuina.\", \"notes\": \"Muuttujat ilman valintaa noudetaan kaikilla arvoilla. Mittari 'Antal döda per 100 000' ja muut ovat laskettuja arvoja; ks. tietokannan kuvaus.\", \"endpoints\": {\"subjects\": {\"name\": \"Luettele aiheet\", \"description\": \"Tilastotietokannan aihealueet id:ineen.\"}}, \"dataset\": {\"subjects\": \"Socialstyrelsen aiheet\"}},\n    \"is\": {\"name\": \"Socialstyrelsen: hagtölugrunnur\", \"publisher\": \"Socialstyrelsen (Heilbrigðis- og félagsmálastofnun Svíþjóðar)\", \"description\": \"Sænskar hagtölur um dánarorsakir, greiningar á legudeildum og göngudeildum, lyf, aðgerðir, meðgöngur og fæðingar, tannheilsu, áverka og fleira. Veldu efni og gildi fyrir hverja breytu; niðurstaðan er sótt í síðum með 5 000 röðum.\", \"notes\": \"Breytur án vals eru sóttar með öllum gildum. Mælikvarðinn 'Antal döda per 100 000' og fleiri eru reiknuð gildi; sjá lýsingu gagnagrunnsins.\", \"endpoints\": {\"subjects\": {\"name\": \"Lista efni\", \"description\": \"Efnissvið í hagtölugrunninum með auðkennum sínum.\"}}, \"dataset\": {\"subjects\": \"Socialstyrelsen efni\"}}\n  }\n}\n");
